with flattened_attrs as (select id, service, log_ts, context, get_json_object(payload_json, '$.user.tier') as user_tier, get_json_object(payload_json, '$.duration') as duration_text, coalesce(context['trace'], 'none') as trace_or_default, context['region'] as region from app_logs) select service, date_trunc('day', log_ts) as activity_day, min(log_ts) as started_at, count(*) as num_rows, (unix_timestamp(max(log_ts)) - unix_timestamp(min(log_ts))) / 60 as span_minutes from flattened_attrs group by 1, 2 order by service desc nulls first
